using System.Security.Claims; using Asp.Versioning; using FluentValidation; using LostFound.Application.Contracts; using LostFound.Domain.Entities; using LostFound.Infrastructure.Persistence; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore;
namespace LostFound.Api.Controllers;
[Authorize,ApiController,ApiVersion(1),Route("api/v{version:apiVersion}/reports")] public sealed class ReportsController(LostFoundDbContext db,IValidator<ReportRequest> validator):ControllerBase{private Guid UserId=>Guid.Parse(User.FindFirstValue(ClaimTypes.NameIdentifier)!);[HttpPost]public async Task<ActionResult> Create(ReportRequest r,CancellationToken ct){var vr=await validator.ValidateAsync(r,ct);if(!vr.IsValid)return BadRequest(new ValidationProblemDetails(vr.ToDictionary()));if(new[]{r.ItemId,r.ReportedUserId,r.MessageId}.Count(x=>x.HasValue)!=1)return BadRequest(new ProblemDetails{Title="Exactly one report target is required",Status=400});if(r.ReportedUserId==UserId)return BadRequest(new ProblemDetails{Title="You cannot report yourself",Status=400});if(r.ItemId.HasValue&&!await db.Items.IgnoreQueryFilters().AnyAsync(x=>x.Id==r.ItemId,ct)||r.ReportedUserId.HasValue&&!await db.Users.AnyAsync(x=>x.Id==r.ReportedUserId,ct))return NotFound();if(r.MessageId.HasValue&&!await db.Messages.AnyAsync(x=>x.Id==r.MessageId&&x.Conversation.Participants.Any(p=>p.UserId==UserId),ct))return NotFound();var report=new Report{ReporterId=UserId,ItemId=r.ItemId,ReportedUserId=r.ReportedUserId,MessageId=r.MessageId,Reason=r.Reason.Trim(),Details=r.Details?.Trim(),Status=ReportStatus.Open};db.Add(report);await db.SaveChangesAsync(ct);return Created($"/api/v1/reports/{report.Id}",new{report.Id});}[Authorize(Policy="Moderator"),HttpGet("moderation")]public async Task<ActionResult> Queue(CancellationToken ct)=>Ok(await db.Reports.AsNoTracking().OrderBy(x=>x.CreatedAtUtc).Select(x=>new{x.Id,x.ReporterId,x.ItemId,x.ReportedUserId,x.MessageId,x.Reason,x.Details,x.Status,x.CreatedAtUtc}).ToListAsync(ct));}
